# 🌊 COMPLETE FLOOD PREDICTION SYSTEM WITH ALL FIGURES
# ==============================

import pandas as pd
import numpy as np
import matplotlib.pyplot as plt
import seaborn as sns
from sklearn.model_selection import train_test_split
from sklearn.preprocessing import StandardScaler, LabelEncoder
from sklearn.ensemble import RandomForestClassifier
from sklearn.linear_model import LogisticRegression
from sklearn.tree import DecisionTreeClassifier
from sklearn.metrics import classification_report, confusion_matrix, accuracy_score
import joblib

# Create figures folder
import os
if not os.path.exists('figures'):
    os.makedirs('figures')

print("=" * 50)
print("🌊 FLOOD PREDICTION SYSTEM - GENERATING FIGURES")
print("=" * 50)

# ---------- 1. LOAD DATA ----------
df = pd.read_csv("final_combined_dataset.csv")

# Cleaning
df['Flood?'] = df['Flood?'].fillna(0).astype(int)
df = df.drop(columns=['Sl'], errors='ignore')

print(f"📊 Dataset loaded: {df.shape[0]} rows, {df.shape[1]} columns")

# ---------- 2. VISUALIZATION 1: Flood Distribution (for report) ----------
plt.figure(figsize=(8, 5))
colors = ['#2ecc71', '#e74c3c']
ax = sns.countplot(x='Flood?', data=df, palette=colors)
plt.title("Flood Distribution (0: No Flood, 1: Flood)", fontsize=14, fontweight='bold')
plt.xlabel("Flood Status", fontsize=12)
plt.ylabel("Count", fontsize=12)

# Add count labels on bars
for i, bar in enumerate(ax.patches):
    ax.text(bar.get_x() + bar.get_width()/2, bar.get_height() + 5, 
            f'{int(bar.get_height())}', ha='center', fontsize=11, fontweight='bold')

plt.xticks([0, 1], ['No Flood', 'Flood'])
plt.tight_layout()
plt.savefig('figures/flood_distribution.png', dpi=150)
plt.close()
print("✅ Figure 1: flood_distribution.png saved")

# ---------- 3. VISUALIZATION 2: Correlation Heatmap ----------
plt.figure(figsize=(14, 10))
numeric_df = df.select_dtypes(include=[np.number])
corr = numeric_df.corr()
mask = np.triu(np.ones_like(corr, dtype=bool))
sns.heatmap(corr, mask=mask, annot=True, cmap='coolwarm', fmt='.2f', 
            linewidths=0.5, annot_kws={'size': 8})
plt.title("Feature Correlation Matrix", fontsize=14, fontweight='bold')
plt.tight_layout()
plt.savefig('figures/correlation_heatmap.png', dpi=150)
plt.close()
print("✅ Figure 2: correlation_heatmap.png saved")

# ---------- 4. VISUALIZATION 3: Rainfall vs Flood Boxplot ----------
plt.figure(figsize=(8, 6))
sns.boxplot(x='Flood?', y='Rainfall', data=df, palette=colors)
plt.title("Rainfall Distribution by Flood Status", fontsize=14, fontweight='bold')
plt.xlabel("Flood Status", fontsize=12)
plt.ylabel("Rainfall (mm)", fontsize=12)
plt.xticks([0, 1], ['No Flood', 'Flood'])
plt.tight_layout()
plt.savefig('figures/rainfall_vs_flood.png', dpi=150)
plt.close()
print("✅ Figure 3: rainfall_vs_flood.png saved")

# ---------- 5. ENCODE CATEGORICAL ----------
encoders = {}
cat_cols = df.select_dtypes(include=['object']).columns

for col in cat_cols:
    le = LabelEncoder()
    df[col] = le.fit_transform(df[col])
    encoders[col] = le

# Features
X = df.drop('Flood?', axis=1)
y = df['Flood?']
feature_names = X.columns.tolist()

# Split
X_train, X_test, y_train, y_test = train_test_split(X, y, test_size=0.3, random_state=42)

# Scaling
scaler = StandardScaler()
X_train_scaled = scaler.fit_transform(X_train)
X_test_scaled = scaler.transform(X_test)

# ---------- 6. TRAIN MODELS ----------
# Random Forest
rf = RandomForestClassifier(random_state=42)
rf.fit(X_train_scaled, y_train)
y_pred_rf = rf.predict(X_test_scaled)

# Logistic Regression
lr = LogisticRegression(max_iter=1000, random_state=42)
lr.fit(X_train_scaled, y_train)
y_pred_lr = lr.predict(X_test_scaled)

# Decision Tree
dt = DecisionTreeClassifier(random_state=42)
dt.fit(X_train_scaled, y_train)
y_pred_dt = dt.predict(X_test_scaled)

# Calculate accuracies
acc_rf = accuracy_score(y_test, y_pred_rf)
acc_lr = accuracy_score(y_test, y_pred_lr)
acc_dt = accuracy_score(y_test, y_pred_dt)

print(f"\n📊 Model Accuracies:")
print(f"   Random Forest: {acc_rf:.2%}")
print(f"   Logistic Regression: {acc_lr:.2%}")
print(f"   Decision Tree: {acc_dt:.2%}")

# ---------- 7. VISUALIZATION 4: Confusion Matrix for Random Forest ----------
cm_rf = confusion_matrix(y_test, y_pred_rf)
plt.figure(figsize=(7, 6))
sns.heatmap(cm_rf, annot=True, fmt='d', cmap='Blues', 
            xticklabels=['No Flood', 'Flood'], 
            yticklabels=['No Flood', 'Flood'],
            annot_kws={'size': 16, 'fontweight': 'bold'})
plt.title("Confusion Matrix - Random Forest Model", fontsize=14, fontweight='bold')
plt.xlabel("Predicted", fontsize=12)
plt.ylabel("Actual", fontsize=12)
plt.tight_layout()
plt.savefig('figures/confusion_matrix.png', dpi=150)
plt.close()
print("✅ Figure 4: confusion_matrix.png saved (Figure 4.2 in report)")

# ---------- 8. VISUALIZATION 5: Feature Importance ----------
feature_imp = pd.DataFrame({
    'Feature': feature_names,
    'Importance': rf.feature_importances_
}).sort_values('Importance', ascending=False)

plt.figure(figsize=(10, 8))
sns.barplot(x='Importance', y='Feature', data=feature_imp.head(10), palette='viridis')
plt.title("Top 10 Feature Importance for Flood Prediction", fontsize=14, fontweight='bold')
plt.xlabel("Importance Score", fontsize=12)
plt.ylabel("Features", fontsize=12)
plt.tight_layout()
plt.savefig('figures/feature_importance.png', dpi=150)
plt.close()
print("✅ Figure 5: feature_importance.png saved (Figure 4.3 in report)")

# ---------- 9. VISUALIZATION 6: Model Accuracy Comparison ----------
models_acc = {
    'Random Forest': acc_rf,
    'Logistic Regression': acc_lr,
    'Decision Tree': acc_dt
}

plt.figure(figsize=(8, 6))
colors_bar = ['#2ecc71', '#3498db', '#e67e22']
bars = plt.bar(models_acc.keys(), models_acc.values(), color=colors_bar)
plt.title("Model Accuracy Comparison", fontsize=14, fontweight='bold')
plt.ylabel("Accuracy", fontsize=12)
plt.ylim(0, 1)
plt.axhline(y=0.92, color='red', linestyle='--', label='Target (92%)')

# Add value labels on bars
for bar, acc in zip(bars, models_acc.values()):
    plt.text(bar.get_x() + bar.get_width()/2, bar.get_height() + 0.01, 
             f'{acc:.1%}', ha='center', fontsize=11, fontweight='bold')

plt.legend()
plt.tight_layout()
plt.savefig('figures/accuracy_comparison.png', dpi=150)
plt.close()
print("✅ Figure 6: accuracy_comparison.png saved (Figure 5.1 in report)")

# ---------- 10. SAVE MODELS ----------
joblib.dump(rf, 'flood_model.pkl')
joblib.dump(scaler, 'scaler.pkl')
joblib.dump(encoders, 'encoders.pkl')
joblib.dump(feature_names, 'features.pkl')

print("\n" + "=" * 50)
print("✅ ALL MODELS AND FILES SAVED SUCCESSFULLY!")
print("=" * 50)
print("\n📁 Figures saved in 'figures' folder:")
print("   1. flood_distribution.png")
print("   2. correlation_heatmap.png")
print("   3. rainfall_vs_flood.png")
print("   4. confusion_matrix.png (Figure 4.2)")
